12	impl<'a> MayHaveSideEffects<'a> for Expression<'a> {
13	    fn may_have_side_effects(&self, ctx: &impl MayHaveSideEffectsContext<'a>) -> bool {
14	        match self {
15	            Expression::Identifier(ident) => ident.may_have_side_effects(ctx),
16	            Expression::NumericLiteral(_)
17	            | Expression::BooleanLiteral(_)
18	            | Expression::StringLiteral(_)
19	            | Expression::BigIntLiteral(_)
20	            | Expression::NullLiteral(_)
21	            | Expression::RegExpLiteral(_)
22	            | Expression::MetaProperty(_)
23	            | Expression::ThisExpression(_)
24	            | Expression::ArrowFunctionExpression(_)
25	            | Expression::FunctionExpression(_)
26	            | Expression::Super(_) => false,
27	            Expression::TemplateLiteral(e) => e.may_have_side_effects(ctx),
28	            Expression::UnaryExpression(e) => e.may_have_side_effects(ctx),
29	            Expression::LogicalExpression(e) => e.may_have_side_effects(ctx),
30	            Expression::ParenthesizedExpression(e) => e.expression.may_have_side_effects(ctx),
31	            Expression::ConditionalExpression(e) => {
32	                if e.test.may_have_side_effects(ctx) {
33	                    return true;
34	                }
35	                // typeof x === 'undefined' ? fallback : x
36	                if is_side_effect_free_unbound_identifier_ref(&e.alternate, &e.test, false, ctx) {
37	                    return e.consequent.may_have_side_effects(ctx);
38	                }
39	                // typeof x !== 'undefined' ? x : fallback
40	                if is_side_effect_free_unbound_identifier_ref(&e.consequent, &e.test, true, ctx) {
41	                    return e.alternate.may_have_side_effects(ctx);
42	                }
43	                e.consequent.may_have_side_effects(ctx) || e.alternate.may_have_side_effects(ctx)
44	            }
45	            Expression::SequenceExpression(e) => {
46	                e.expressions.iter().any(|e| e.may_have_side_effects(ctx))
47	            }
48	            Expression::BinaryExpression(e) => e.may_have_side_effects(ctx),
49	            Expression::ObjectExpression(object_expr) => {
50	                object_expr.properties.iter().any(|property| property.may_have_side_effects(ctx))
51	            }
52	            Expression::ArrayExpression(e) => e.may_have_side_effects(ctx),
53	            Expression::ClassExpression(e) => e.may_have_side_effects(ctx),
54	            Expression::PrivateInExpression(e) => {
55	                if e.right.may_have_side_effects(ctx) {
56	                    return true;
57	                }
58	                // `#x in y` throws when `y` is not an object.
59	                !e.right.value_type(ctx).is_object()
60	            }
61	            Expression::ChainExpression(e) => e.expression.may_have_side_effects(ctx),
62	            match_member_expression!(Expression) => {
63	                self.to_member_expression().may_have_side_effects(ctx)
64	            }
65	            Expression::CallExpression(e) => e.may_have_side_effects(ctx),
66	            Expression::NewExpression(e) => e.may_have_side_effects(ctx),
67	            Expression::TaggedTemplateExpression(e) => e.may_have_side_effects(ctx),
68	            Expression::AssignmentExpression(e) => e.may_have_side_effects(ctx),
69	            Expression::UpdateExpression(e) => e.may_have_side_effects(ctx),
70	            _ => true,
71	        }
72	    }
73	}
