87	impl<'a> MayHaveSideEffects<'a> for TemplateLiteral<'a> {
88	    fn may_have_side_effects(&self, ctx: &impl MayHaveSideEffectsContext<'a>) -> bool {
89	        self.expressions.iter().any(|e| {
90	            // ToString is called for each expression.
91	            // If the expression is a Symbol or ToPrimitive returns a Symbol, an error is thrown.
92	            // ToPrimitive returns the value as-is for non-Object values, so we can use it instead of ToString here.
93	            e.to_primitive(ctx).is_symbol() != Some(false) || e.may_have_side_effects(ctx)
94	        })
95	    }
96	}
