/// Whether the name is a well-known built-in global object whose access is side-effect free.
///
/// Accessing these identifiers is considered side-effect free regardless of any additional
/// configuration.
#[rustfmt::skip]
fn is_known_global_object(name: &str) -> bool {
    matches!(name,
        "Math" | "Array" | "Object" | "JSON" | "Reflect" | "Symbol" | "Promise"
            | "Map" | "Set" | "WeakMap" | "WeakSet" | "parseInt" | "parseFloat"
            | "isNaN" | "isFinite" | "encodeURI" | "decodeURI" | "globalThis")
}

/// Whether the name is a known-safe environment global whose access is side-effect free.
///
/// These are commonly available host globals that are safe to access when they are known
/// to be global references (i.e. included in the explicit global variable list).
fn is_known_safe_environment_global(name: &str) -> bool {
    matches!(name, "console" | "document" | "window" | "fetch")
}

